import sys
data = sys.stdin.read().split()
if data:
    n = int(data[0])
    ratings = [int(x) for x in data[1:1+n]]
    candies = [1] * n
    for i in range(1, n):
        if ratings[i] > ratings[i-1]: candies[i] = candies[i-1] + 1
    for i in range(n - 2, -1, -1):
        if ratings[i] > ratings[i+1]: candies[i] = max(candies[i], candies[i+1] + 1)
    print(sum(candies))
